#else
#define debug(...)
#define debugArr(...)
#endif
const int maxn = 300005;

int n, m, k;
vector<int> sectors[maxn];
long long p[maxn];

struct Meteor {
    int l, r;
    long long a;
} meteors[maxn];

long long bit[maxn];

void update(int idx, long long val) {
    for (; idx <= m; idx += idx & -idx) {
        bit[idx] += val;
    }
}

void rupdate(int l, int r, long long val) {
    if (l <= r) {
        update(l, val);
        update(r + 1, -val);
    } else {
        update(l, val);
        update(m + 1, -val);
        update(1, val);
        update(r + 1, -val);
    }
}
long long query(int idx) {
    long long sum = 0;
    for (; idx > 0; idx -= idx & -idx) {
        sum += bit[idx];
    }
    return sum;
}

int l[maxn], r[maxn], ans[maxn];
vector<int> bucket[maxn];
int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;

    for (int i = 1; i <= m; i++) {
        int owner;
        cin >> owner;
        sectors[owner].push_back(i);
    }

    for (int i = 1; i <= n; i++) {
        cin >> p[i];
    }

    cin >> k;
    for (int i = 1; i <= k; i++) {
        cin >> meteors[i].l >> meteors[i].r >> meteors[i].a;
    }
    for (int i = 1; i <= n; i++) {
        l[i] = 1;
        r[i] = k + 1;
    }

    bool changed = true;
    while (changed) {
        changed = false;
        for (int i = 1; i <= k; i++) {
            bucket[i].clear();
        }
        for (int i = 1; i <= n; i++) {
            if (l[i] < r[i]) {
                int mid = (l[i] + r[i]) / 2;
                bucket[mid].push_back(i);
                changed = true;
            }
        }

        if (!changed) break;
        fill(bit, bit + m + 2, 0);
        for (int i = 1; i <= k; i++) {
            rupdate(meteors[i].l, meteors[i].r, meteors[i].a);
            for (int country : bucket[i]) {
                long long total = 0;
                for (int sec : sectors[country]) {
                    total += query(sec);
                    if (total >= p[country]) break;
                }

                if (total >= p[country]) {
                    r[country] = i;
                } else {
                    l[country] = i + 1;
                }
            }
        }
    }

    for (int i = 1; i <= n; i++) {
        if (l[i] <= k) {
            cout << l[i] << "\n";
        } else {
            cout << "NIE\n";
        }
    }

}